import{_ as t,o as s,c as n,a2 as e}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"同桌的你","description":"","frontmatter":{"title":"同桌的你","date":"2026-09-03T00:00:00.000Z","tags":["口琴","进阶"]},"headers":[],"relativePath":"study/harmonica/scores/12-同桌的你.md","filePath":"study/harmonica/scores/12-同桌的你.md","lastUpdated":1788506840000}'),l={name:"study/harmonica/scores/12-同桌的你.md"};function d(o,a,i,r,p,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="_12-·-同桌的你-⭐⭐⭐-高晓松词曲-老狼" tabindex="-1">12 · 同桌的你 ⭐⭐⭐（高晓松词曲 / 老狼） <a class="header-anchor" href="#_12-·-同桌的你-⭐⭐⭐-高晓松词曲-老狼" aria-label="Permalink to &quot;12 · 同桌的你 ⭐⭐⭐（高晓松词曲 / 老狼）&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>难度</td><td>⭐⭐⭐ 进阶</td></tr><tr><td>拍号/速度</td><td>4/4 · ♩= 76（校园民谣的&quot;慢&quot;）</td></tr><tr><td>口琴</td><td>C 调</td></tr><tr><td>目标</td><td>弱奏与气声、青春的克制感</td></tr></tbody></table><h2 id="简谱-c-调-·-主歌首段-副歌首句" tabindex="-1">简谱（C 调 · 主歌首段+副歌首句） <a class="header-anchor" href="#简谱-c-调-·-主歌首段-副歌首句" aria-label="Permalink to &quot;简谱（C 调 · 主歌首段+副歌首句）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>明天你是否会想起：</span></span>
<span class="line"><span>3  3  3  3  2  1  2 | 3 - - - |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>昨天你写的日记：</span></span>
<span class="line"><span>3  3  3  2  1  2 | 1 - - - |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>明天你是否还惦记：</span></span>
<span class="line"><span>3  3  3  3  2  1  2 | 3 - - - |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>曾经最爱哭的你：</span></span>
<span class="line"><span>6, 1  2  1  6, 5, 6, | 1 - - - |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>谁娶了多愁善感的你：</span></span>
<span class="line"><span>6  6  6  5  6  1&#39; 6 | 5 - - - |</span></span></code></pre></div><h2 id="吹奏要点" tabindex="-1">吹奏要点 <a class="header-anchor" href="#吹奏要点" aria-label="Permalink to &quot;吹奏要点&quot;">​</a></h2><ol><li>全曲的魂是&quot;<strong>轻</strong>&quot;：气流减半，像怕吵醒回忆——能吹多轻吹多轻，音断意不断</li><li><code>3 3 3 3 2 1 2</code> 连续同音+级进，靠<strong>音头的轻重交替</strong>做出民谣的絮语感</li><li>副歌 <code>6 6 6 5 6 1&#39;</code> 情绪上扬但仍克制：加 20% 气即可，不要&quot;喊&quot;</li><li>结尾渐慢渐弱，最后一句可以只吹单音渐消失（收音练法）</li></ol><h2 id="练习任务" tabindex="-1">练习任务 <a class="header-anchor" href="#练习任务" aria-label="Permalink to &quot;练习任务&quot;">​</a></h2><ul><li>[ ] 用你能做到的最小音量吹完整曲且音准不丢</li><li>[ ] 对比录音：第一次 vs 第十次，找出&quot;絮语感&quot;出现的回合</li></ul><h2 id="🗺️-完整演奏地图" tabindex="-1">🗺️ 完整演奏地图 <a class="header-anchor" href="#🗺️-完整演奏地图" aria-label="Permalink to &quot;🗺️ 完整演奏地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段落</th><th>内容</th><th>本谱覆盖</th></tr></thead><tbody><tr><td>前奏</td><td>8 小节（口琴+吉他，原曲即口琴编配）</td><td>—</td></tr><tr><td>主歌 A（4 句）</td><td>明天你是否会想起…曾经最爱哭的你</td><td>✅ 已给 4 句</td></tr><tr><td>副歌 B（4 句）</td><td>谁娶了多愁善感的你…谁给你做的嫁衣</td><td>✅ 已给首句，后 3 句同构微变</td></tr><tr><td>尾声</td><td>谁把你的长发盘起（渐弱）</td><td>同 B</td></tr></tbody></table><ul><li>和弦参考：<code>C - Em - F - G</code> 与 <code>Am - F - G - C</code> 交替</li><li>完整词谱获取：见下方渠道</li></ul><h2 id="📖-完整词谱获取渠道-合法" tabindex="-1">📖 完整词谱获取渠道（合法） <a class="header-anchor" href="#📖-完整词谱获取渠道-合法" aria-label="Permalink to &quot;📖 完整词谱获取渠道（合法）&quot;">​</a></h2><ol><li><strong>曲谱网站</strong>：歌谱简谱网、曲谱自珍网等（个人学习打印常规授权范围）</li><li><strong>音乐 App 曲谱功能</strong>：网易云音乐/QQ 音乐内置歌词+部分曲谱</li><li><strong>正版歌本</strong>：《口琴演奏自学教程》《流行歌曲口琴曲集》等出版物</li><li><strong>最实用</strong>：本页&quot;演奏地图&quot; + 原曲伴奏（各音乐平台均有）——地图定孔位，耳朵定细节</li></ol>`,13)])])}const _=t(l,[["render",d]]);export{u as __pageData,_ as default};
